        "promised_delivery_date": delivery_date,
        "delivery_date_passed": delivery_date_passed,
        "delivery_date_confidence": resolved["confidence"],
        "needs_review": (
            defect_count_confidence is None
            or defect_count_confidence < REVIEW_BELOW
